from bank_core import *
def questions(v=0):
 b=Bank(5,v);a=3+v;k=2+v;t='عبارت جبری و اتحاد';f='تجزیه و کاربرد اتحادها';u='نابرابری و نامعادله'
 b.n(1,'ضریب علامت‌دار یک جمله',t,f'ضریب x در عبارت −{a}x+{a+2} چند است؟',-a,'علامت منفی جزئی از ضریب جمله است.',f'(-{a}*x+{a+2}).coeff(x)')
 b.n(1,'درجهٔ تک‌جمله‌ای نسبت به یک متغیر',t,f'درجهٔ {a}x^{k}y^{k+2} نسبت به y چند است؟',k+2,'برای درجه نسبت به یک متغیر، فقط نمای همان متغیر را بخوان.',f'degree({a}*x**{k}*y**{k+2},y)')
 b.n(1,'درجهٔ کل تک‌جمله‌ای',t,f'درجهٔ کل {a}x^{k}y^{k+2} نسبت به x و y چند است؟',2*k+2,'درجهٔ کل یک تک‌جمله‌ای، مجموع نماهای متغیرهای آن است.',f'Poly({a}*x**{k}*y**{k+2},x,y).total_degree()')
 b.n(1,'جمله‌های هم‌نوع و جمع ضریب‌ها',t,f'پس از ساده‌کردن {a}x+{a+2}x−{k}، ضریب x چند است؟',2*a+2,'فقط جمله‌هایی با بخش حرفی یکسان را جمع کن.',f'expand({a}*x+{a+2}*x-{k}).coeff(x)')
 b.n(1,'مقدار عددی عبارت جبری',t,f'مقدار {k}x²−x را برای x=−{a} حساب کن.',k*a*a+a,'مقدار منفی را داخل پرانتز جایگذاری کن و ترتیب عملیات را نگه دار.',f'{k}*(-{a})**2-(-{a})')
 b.n(1,'خاصیت توزیع‌پذیری',t,f'در بسط {k}({a}x−{a+1})، جملهٔ ثابت چند است؟',-k*(a+1),'عامل بیرونی باید در هر دو جملهٔ داخل پرانتز ضرب شود.',f'expand({k}*({a}*x-{a+1})).coeff(x,0)')
 b.m(1,'تعریف اتحاد در مقایسه با معادله',t,'کدام توصیفِ اتحاد درست است؟','تساوی‌ای که برای همهٔ مقدارهای مجاز متغیرها درست است',['تساوی‌ای که فقط یک جواب دارد','هر عبارتی که توان دو دارد','نام دیگر نامعادله'],'اتحاد یک رابطهٔ همگانی روی مقدارهای مجاز است؛ یک جواب خاص آن را ثابت نمی‌کند.')
 b.n(1,'جملهٔ میانی مربع مجموع',t,f'ضریب x در بسط (x+{a})² چند است؟',2*a,'جملهٔ میانی برابر دو برابر حاصل ضرب دو جمله است.',f'expand((x+{a})**2).coeff(x)')
 b.n(1,'علامت جملهٔ میانی مربع تفاضل',t,f'ضریب x در بسط (x−{a})² چند است؟',-2*a,'در مربع تفاضل، جملهٔ میانی منفی و جملهٔ پایانی مثبت است.',f'expand((x-{a})**2).coeff(x)')
 b.n(1,'حذف جملهٔ میانی در مزدوج',t,f'جملهٔ ثابت در حاصل (x+{a})(x−{a}) چند است؟',-a*a,'حاصل دو مزدوج، تفاضل مربع‌هاست و جملهٔ x ندارد.',f'expand((x+{a})*(x-{a})).coeff(x,0)')
 b.m(1,'جهت نامساوی در جمع ثابت',u,f'اگر x<{a} باشد، کدام نتیجه درست است؟',f'x+{k}<{a+k}',[f'x+{k}>{a+k}',f'x+{k}={a+k}',f'x<{a-k}'],'افزودن یک عدد یکسان به دو طرف، جهت نامساوی را عوض نمی‌کند.')
 b.m(1,'جهت نامساوی در ضرب منفی',u,f'اگر x<{a} باشد، کدام رابطه پس از ضرب در −{k} درست است؟',f'−{k}x>−{k*a}',[f'−{k}x<−{k*a}',f'−{k}x=−{k*a}',f'x>{a}'],'ضرب یا تقسیم دو طرف نامساوی در عدد منفی، جهت علامت را عوض می‌کند.')
 b.n(2,'درجهٔ چندجمله‌ای پس از ساده‌سازی',t,f'درجهٔ چندجمله‌ای {a}x³+2x²−{a}x³+{k}x چند است؟',2,'ابتدا جمله‌های هم‌نوع را ساده کن؛ بزرگ‌ترین توان باقی‌مانده درجه است.',f'degree(expand({a}*x**3+2*x**2-{a}*x**3+{k}*x),x)')
 b.n(2,'ضرب تک‌جمله‌ای‌ها و ضریب حاصل',t,f'ضریب عددی حاصل ({a}x²y)(−{k}xy³) چند است؟',-a*k,'ضریب‌های عددی ضرب می‌شوند و نماهای هر متغیر جدا جمع می‌شوند.',f'expand(({a}*x**2*y)*(-{k}*x*y**3)).coeff(x,3).coeff(y,4)')
 b.n(2,'بسط مربع مجموع با ضریب متغیر',t,f'ضریب x در بسط ({k}x+{a})² چند است؟',2*k*a,'جملهٔ میانی دو برابر حاصل ضرب kx و a است.',f'expand(({k}*x+{a})**2).coeff(x)')
 b.n(2,'اتحاد جملهٔ مشترک',t,f'ضریب x در بسط (x+{a})(x+{a+2}) چند است؟',2*a+2,'در اتحاد جملهٔ مشترک، ضریب x برابر مجموع دو عدد ثابت است.',f'expand((x+{a})*(x+{a+2})).coeff(x)')
 b.m(2,'تجزیه با عامل مشترک',f,f'کدام عبارت با {a}x²+{a*k}x یکسان است؟',f'{a}x(x+{k})',[f'{a}x(x−{k})',f'x({a}x+{k})',f'{a}(x+{k})'],'بزرگ‌ترین عامل عددی و حرفی مشترک را بیرون بکش؛ با ضرب دوباره بررسی کن.',expression=f'{a}*x**2+{a*k}*x',option_exprs=[f'{a}*x*(x+{k})',f'{a}*x*(x-{k})',f'x*({a}*x+{k})',f'{a}*(x+{k})'])
 b.m(2,'تجزیهٔ تفاضل دو مربع',f,f'تجزیهٔ x²−{a*a} کدام است؟',f'(x−{a})(x+{a})',[f'(x−{a})²',f'(x+{a})²',f'x(x−{a*a})'],'تفاضل دو مربع به حاصل ضرب دو مزدوج تجزیه می‌شود.',expression=f'x**2-{a*a}',option_exprs=[f'(x-{a})*(x+{a})',f'(x-{a})**2',f'(x+{a})**2',f'x*(x-{a*a})'])
 b.m(2,'تجزیهٔ مربع کامل',f,f'تجزیهٔ x²−{2*a}x+{a*a} کدام است؟',f'(x−{a})²',[f'(x+{a})²',f'(x−{a})(x+{a})',f'x(x−{2*a})'],'علامت جملهٔ میانی و مربع جملهٔ ثابت را با الگوی مربع تفاضل تطبیق بده.',expression=f'x**2-{2*a}*x+{a*a}',option_exprs=[f'(x-{a})**2',f'(x+{a})**2',f'(x-{a})*(x+{a})',f'x*(x-{2*a})'])
 b.n(2,'مجهول در تجزیهٔ سه‌جمله‌ای',f,f'اگر x²+{2*a+1}x+{a*(a+1)}=(x+{a})(x+c) باشد، c چند است؟',a+1,'دو ثابت باید هم مجموع و هم حاصل ضرب درست داشته باشند.',f'({2*a+1})-{a}')
 b.n(2,'محاسبهٔ عددی با مزدوج',f,f'حاصل ({100+a})×({100-a}) چند است؟',10000-a*a,'دو عدد در دو سوی صد قرار دارند؛ از تفاضل مربع‌ها استفاده کن.',f'({100+a})*({100-a})')
 b.n(2,'مرز نامعادلهٔ خطی مثبت',u,f'مرز مجموعهٔ جوابِ {k}x+{a}≤{a+5*k} کدام عدد است؟',5,'عدد ثابت را کم کن و بر ضریب مثبت تقسیم کن؛ مرز همان جواب معادلهٔ متناظر است.',f'({a+5*k}-{a})/{k}')
 b.n(2,'مرز نامعادله با تقسیم منفی',u,f'نامعادلهٔ −{k}x+{a}<{a+4*k} به x>c تبدیل می‌شود؛ c چند است؟',-4,'هنگام تقسیم بر ضریب منفی، جهت علامت را وارونه کن.',f'({a+4*k}-{a})/(-{k})')
 b.n(2,'کمترین صحیح در نامعادلهٔ اکید',u,f'کوچک‌ترین عدد صحیحی که x>{a}.4 را برآورده می‌کند چند است؟',a+1,'عدد صحیحِ سمت راست کران را انتخاب کن؛ کرانِ اکید عضو مجموعهٔ جواب نیست.',f'ceiling(Rational({10*a+4},10))')
 b.n(3,'تفریق دو مربع دوجمله‌ای',t,f'ضریب x در ساده‌شدهٔ (x+{a})²−(x−{a})² چند است؟',4*a,'منفیِ پرانتز دوم همهٔ جمله‌های آن را عوض می‌کند؛ جمله‌های مربعی و ثابت حذف می‌شوند.',f'expand((x+{a})**2-(x-{a})**2).coeff(x)')
 b.n(3,'جمع دو مربع دوجمله‌ای',t,f'جملهٔ ثابتِ (x+{a})²+(x−{a})² چند است؟',2*a*a,'در جمع دو مربع، جمله‌های خطی قرینه حذف و دو جملهٔ ثابت جمع می‌شوند.',f'expand((x+{a})**2+(x-{a})**2).coeff(x,0)')
 b.m(3,'تجزیه با گروه‌بندی',f,f'کدام عبارت برابر ax+ay+{k}x+{k}y است؟',f'(a+{k})(x+y)',[f'(a−{k})(x+y)',f'(a+{k})(x−y)',f'a(x+y+{k})'],'از دو گروه عامل مشترک بگیر؛ سپس عامل دوجمله‌ای مشترک را بیرون بکش.',expression=f'a*x+a*y+{k}*x+{k}*y',option_exprs=[f'(a+{k})*(x+y)',f'(a-{k})*(x+y)',f'(a+{k})*(x-y)',f'a*(x+y+{k})'])
 b.m(3,'عامل‌گیری پیش از اتحاد',f,f'تجزیهٔ کامل {k}x²−{k*a*a} کدام است؟',f'{k}(x−{a})(x+{a})',[f'{k}(x−{a})²',f'({k}x−{a})({k}x+{a})',f'{k}x(x−{a*a})'],'اول عامل عددی مشترک را بیرون بکش و بعد تفاضل دو مربع را تجزیه کن.',expression=f'{k}*x**2-{k*a*a}',option_exprs=[f'{k}*(x-{a})*(x+{a})',f'{k}*(x-{a})**2',f'({k}*x-{a})*({k}*x+{a})',f'{k}*x*(x-{a*a})'])
 b.s(3,'خاصیت صفر شدن حاصل ضرب',f,f'مجموعهٔ جواب‌های (x−{a})(x+{k})=0 را بنویس.',[a,-k],'در حاصل ضرب صفر، دست‌کم یکی از عامل‌ها صفر است؛ دو حالت را جدا حل کن.')
 b.n(3,'بازیابی ضریب برای مربع کامل',f,f'اگر x²+cx+{a*a}=(x−{a})² باشد، c چند است؟',-2*a,'علامت منفی داخل مربع، جملهٔ میانی منفی می‌سازد.',f'expand((x-{a})**2).coeff(x)')
 b.n(3,'حل نامعادله با پرانتز در دو طرف',u,f'نامعادلهٔ {k}(x−{a})≤({k-1})x+{2*a} به x≤c تبدیل می‌شود؛ c چند است؟',(k+2)*a,'پرانتزها را باز کن، جمله‌های x را یک طرف و ثابت‌ها را طرف دیگر جمع کن.',f'{k}*{a}+{2*a}')
 b.n(3,'حل نامعادلهٔ کسری با مخرج ثابت مثبت',u,f'نامعادلهٔ (x−{a})/2≥(x+{a})/3 به x≥c می‌رسد؛ c چند است؟',5*a,'هر دو طرف را در شش مثبت ضرب کن؛ سپس نامعادلهٔ خطی را حل کن.',f'3*{a}+2*{a}')
 b.n(3,'شمارش جواب صحیح در اشتراک دو نامعادله',u,f'چند عدد صحیح شرط‌های x>{a}/2 و x≤{a+4} را هم‌زمان دارند؟',a+4-a//2,'اشتراک دو شرط یک بازه است؛ عدد صحیحِ کران باز را درست کنار بگذار.',f'{a+4}-floor(Rational({a},2))')
 cost=7+v;budget=cost*6+3
 b.n(3,'مدل‌سازی محدودیت بودجه',u,f'قیمت هر دفتر {cost} واحد و بودجه {budget} واحد است؛ بدون هزینهٔ دیگر حداکثر چند دفتر می‌توان خرید؟',6,'تعداد خرید باید صحیح و حاصل هزینه از بودجه بیشتر نباشد.',f'floor(Rational({budget},{cost}))')
 b.n(3,'بزرگ‌ترین جواب صحیح نامعادلهٔ منفی',u,f'بزرگ‌ترین عدد صحیحی که −2x>−{2*a+1} را برآورده کند چند است؟',a,'با تقسیم بر منفی دو، علامت برمی‌گردد و x از یک عدد نیمه‌صحیح کوچک‌تر می‌شود.',f'ceiling(Rational({2*a+1},2))-1')
 b.tf(3,'شرط علامت عامل در ضرب نامعادله',u,'اگر a<b باشد، بدون دانستن علامت c می‌توان نتیجه گرفت ac<bc.',False,'ضرب در مثبت جهت را حفظ، ضرب در منفی جهت را عوض و ضرب در صفر دو طرف را برابر می‌کند.')
 b.n(4,'بازیابی دو ضریب از همانی',t,f'اگر (x+{a})(x+c)=x²+{2*a+2}x+d یک اتحاد باشد، مقدار d چند است؟',a*(a+2),'از ضریب x، c را پیدا کن و سپس ثابت حاصل ضرب را حساب کن.',f'{a}*({2*a+2}-{a})')
 b.n(4,'کمینهٔ عبارت مربع کامل',f,f'کمترین مقدار x²−{2*a}x+{a*a+3} روی عددهای حقیقی چند است؟',3,'عبارت را به مربع کامل به‌علاوهٔ ثابت تبدیل کن؛ مربع کمینهٔ صفر دارد.',f'({a})**2-{2*a}*({a})+{a*a+3}')
 b.n(4,'حذف مجهول با دو اتحاد',t,f'اگر x+y={a+5} و xy={a} باشد، x²+y² چند است؟',(a+5)**2-2*a,'مربع مجموع، دو برابر حاصل ضرب را هم دارد؛ آن بخش را کم کن.',f'({a+5})**2-2*{a}')
 b.n(4,'مربع تفاضل از مجموع و حاصل ضرب',t,f'اگر x+y={a+6} و xy={a+1} باشد، (x−y)² چند است؟',(a+6)**2-4*(a+1),'مربع تفاضل برابر مربع مجموع منهای چهار برابر حاصل ضرب است.',f'({a+6})**2-4*({a+1})')
 b.n(4,'ارزیابی سریع اتحاد با جملهٔ مشترک',f,f'حاصل ({50+a})({50+a+1})−({50+a})² چند است؟',50+a,'عامل مشترک را بیرون بکش؛ تفاضل دو عامل داخل پرانتز برابر یک است.',f'({50+a})*({51+a})-({50+a})**2')
 b.n(4,'تجزیهٔ تفاضل مربع‌های جبری',f,f'در ساده‌شدهٔ ({k}x+{a})²−({k}x−{a})²، ضریب x چند است؟',4*k*a,'دو مربع را به صورت حاصل ضرب مجموع و تفاضل تجزیه کن.',f'expand(({k}*x+{a})**2-({k}*x-{a})**2).coeff(x)')
 b.m(4,'نامعادلهٔ ناسازگار پس از حذف متغیر',u,f'مجموعهٔ جوابِ {k}(x+{a})>{k}x+{k*a+1} کدام است؟','∅',['همهٔ عددهای حقیقی',f'x>{a}',f'x<{a}'],'پس از حذف جمله‌های برابر، یک نامساوی عددیِ نادرست باقی می‌ماند؛ هیچ x آن را درست نمی‌کند.')
 b.m(4,'نامعادلهٔ همواره درست پس از ساده‌سازی',u,f'مجموعهٔ جوابِ {k}(x+{a})<{k}x+{k*a+1} کدام است؟','همهٔ عددهای حقیقی',['∅',f'x>{a}',f'x<{a}'],'بعد از حذف x، نامساوی عددیِ درست به دست می‌آید و هیچ محدودیتی بر x نیست.')
 b.n(4,'ترکیب محدودیت تعداد و هزینهٔ ثابت',u,f'هزینهٔ ثابت یک سفارش {a} و هزینهٔ هر قلم {k} واحد است؛ بودجه {a+7*k+1} واحد است؛ حداکثر تعداد صحیح قلم چند است؟',7,'هزینهٔ ثابت را از بودجه کم کن، بر هزینهٔ هر قلم تقسیم و تعداد را رو به پایین صحیح کن.',f'floor(Rational({a+7*k+1}-{a},{k}))')
 b.n(4,'تعداد عامل‌های صفرکنندهٔ یک چندجمله‌ای تجزیه‌شده',f,f'معادلهٔ x(x−{a})(x+{k})=0 چند جواب حقیقی متمایز دارد؟',3,'سه عامل خطی، سه جواب صفر، a و منفی k می‌دهند؛ در این داده‌ها هیچ دو جواب برابر نیستند.', 'Integer(3)')
 b.essay(2,'اثبات هندسی اتحاد مربع مجموع',t,'با تقسیم یک مربعِ ضلع a+b به چهار ناحیه، اتحاد مربع مجموع را توضیح بده؛ a,b>0.','مساحت مربع بزرگ (a+b)² است؛ دو مربع a² و b² و دو مستطیل ab آن را می‌پوشانند، پس (a+b)²=a²+2ab+b².',['تعریف اندازه‌های مثبت.','چهار ناحیه و مساحت هرکدام.','برابری مجموع مساحت‌ها.'])
 b.essay(3,'کنترل تجزیه با ضرب معکوس',f,f'عبارت x²−{a*a} را تجزیه کن و درستی تجزیه را با ضرب بررسی کن.',f'(x−{a})(x+{a})؛ جمله‌های خطی حذف می‌شوند و حاصل x²−{a*a} است.',['دو عامل مزدوج.','ضرب همهٔ جمله‌ها.','حذف جمله‌های قرینه.'])
 b.essay(3,'توضیح تغییر جهت در تقسیم منفی',u,'با یک مثال عددی توضیح بده چرا تقسیم دو طرف نامساوی بر عدد منفی جهت را عوض می‌کند.','از 2<5 با تقسیم بر −1 به −2>−5 می‌رسیم؛ قرینه کردن، جای دو نقطه روی محور را معکوس می‌کند.',['مثال نامساوی درست.','دو طرفِ تقسیم‌شده و جهت درست.','توضیح ترتیب روی محور.'])
 b.essay(4,'فرق حل معادله و تشخیص اتحاد',t,'آیا x²+4=x²+2x+4 اتحاد است؟ اگر نیست برای چه xهایی درست است؟','اتحاد نیست؛ با حذف جمله‌های برابر، 2x=0 و فقط x=0 به دست می‌آید.',['آزمون همگانی بودن.','ساده‌سازی معادله.','جواب یکتا و نتیجه.'])
 for q in b.rows:
  adjusted={'تعداد عامل\u200cهای صفرکنندهٔ یک چندجمله\u200cای تجزیه\u200cشده': 2, 'ترکیب محدودیت تعداد و هزینهٔ ثابت': 3, 'ارزیابی سریع اتحاد با جملهٔ مشترک': 3}.get(q['objective'])
  if adjusted:q['level']=adjusted;q['difficulty']=LEVELS[adjusted-1]
 return b.finish()
